questions.codesnippet:
SELECT name FROM agents a
WHERE EXISTS (SELECT 1 FROM properties p
  WHERE p.agent_id = a.id);

SELECT d.city, ROUND(d.avg_price, 2) AS avg_price
FROM (SELECT city, AVG(price) AS avg_price
      FROM properties GROUP BY city) d;

SELECT name,
  (SELECT AVG(rating) FROM agents) AS market_avg
FROM agents;

SELECT id FROM properties p
WHERE price = (SELECT MAX(price) FROM properties p2
               WHERE p2.city = p.city);
